"""Exact best-five Hold'em evaluator; no files or optional dependencies.

Cards use rank-major ids (2..A), suits SHDC. Keys compare lexicographically
as category followed by five four-bit rank fields, matching the legacy bot.
"""
RANKS = '23456789TJQKA'
SUITS = 'SHDC'
DECK = tuple((rank + suit for rank in RANKS for suit in SUITS))
CARD_IDS = {card: index for index, card in enumerate(DECK)}
CARD_BITS = tuple((1 << card for card in range(52)))

def _straight(mask):
    for high in range(12, 3, -1):
        run = 31 << high - 4
        if mask & run == run:
            return high + 2
    return 5 if mask & 4111 == 4111 else 0
STRAIGHTS = tuple((_straight(mask) for mask in range(8192)))

def _top(mask, count):
    key = 0
    for index in range(count):
        bit = mask.bit_length() - 1
        key |= bit + 2 << 16 - 4 * index
        mask ^= 1 << bit
    return key

class ExactRanker:

    def rank(self, cards):
        """Exact rank of five to seven distinct, valid card ids."""
        seen = pairs = trips = quads = 0
        suits = [0, 0, 0, 0]
        for card in cards:
            bit = 1 << card // 4
            quads |= trips & bit
            trips |= pairs & bit
            pairs |= seen & bit
            seen |= bit
            suits[card % 4] |= bit
        flush = next((mask for mask in suits if mask.bit_count() >= 5), 0)
        if flush and STRAIGHTS[flush]:
            return 8 << 20 | STRAIGHTS[flush] << 16
        if quads:
            bit = quads.bit_length() - 1
            return 7 << 20 | bit + 2 << 16 | _top(seen ^ 1 << bit, 1) >> 4
        if trips:
            bit = trips.bit_length() - 1
            other = pairs & ~(1 << bit)
            if other:
                return 6 << 20 | bit + 2 << 16 | _top(other, 1) >> 4
        if flush:
            return 5 << 20 | _top(flush, 5)
        if STRAIGHTS[seen]:
            return 4 << 20 | STRAIGHTS[seen] << 16
        if trips:
            bit = trips.bit_length() - 1
            return 3 << 20 | bit + 2 << 16 | _top(seen ^ 1 << bit, 2) >> 4
        if pairs.bit_count() >= 2:
            first = pairs.bit_length() - 1
            second = (pairs ^ 1 << first).bit_length() - 1
            remaining = seen & ~(1 << first) & ~(1 << second)
            return 2 << 20 | first + 2 << 16 | second + 2 << 12 | _top(remaining, 1) >> 8
        if pairs:
            bit = pairs.bit_length() - 1
            return 1 << 20 | bit + 2 << 16 | _top(seen ^ 1 << bit, 3) >> 4
        return _top(seen, 5)

