"""Shared public betting-line features and Hold'em range priors."""
from itertools import combinations
AGGRESSION = frozenset(('bet', 'raise_to', 'raise', 'all_in'))
UNKNOWN, PASSIVE, OPEN, OPEN_JAM, RERAISE, DEEP_RAISE = range(6)
LOOSE = ((1.0, 1.0, 1.0), (1.0, 0.8, 0.5), (1.0, 0.55, 0.15), (1.0, 0.5, 0.15), (1.0, 0.25, 0.02), (1.0, 0.25, 0.02))
SHARP = ((1.0, 1.0, 1.0), (1.0, 0.55, 0.25), (1.0, 0.3, 0.04), (1.0, 0.12, 0.01), (1.0, 0.1, 0.005), (1.0, 0.1, 0.005))

def hand_type(first, second):
    low, high = sorted((first // 4 + 2, second // 4 + 2))
    return (high, low, first % 4 == second % 4)

def button_open(first, second):
    high, low, suited = hand_type(first, second)
    return high == low or high >= 12 or (high == 11 and (suited or low >= 5)) or (high == 10 and low >= (3 if suited else 6)) or (high == 9 and low >= (4 if suited else 7)) or (high == 8 and low >= (5 if suited else 7)) or (suited and (high, low) in {(7, 5), (7, 6), (6, 5), (5, 4)})

def value_raise(first, second):
    high, low, suited = hand_type(first, second)
    return high == low >= 8 or (high == 14 and low >= (11 if suited else 12)) or (high == 13 and low == 12 and suited)

def _tier(core, fringe):
    return 0 if core else 1 if fringe else 2

def buckets(first, second):
    high, low, suited = hand_type(first, second)
    opens = button_open(first, second)
    raises = value_raise(first, second)
    premium = high == low >= 12 or (high == 14 and low == 13)
    fringe = suited or low >= 7
    return (0, _tier(opens, fringe), _tier(opens, fringe), _tier(raises, opens), _tier(raises, opens), _tier(premium, opens))
PAIRS = tuple(((a, b, CARD_BITS[a] | CARD_BITS[b], buckets(a, b)) for a, b in combinations(range(52), 2)))

def preflop_line(history, opponent_id, big_blind, starting_stack):
    """Return the strongest preflop commitment the opponent took part in."""
    raises = 0
    last_total = 0
    line = UNKNOWN
    for move in history:
        if move.street != 'preflop':
            continue
        action = move.action
        if action in AGGRESSION:
            raises += 1
            last_total = move.amount or 0
            if move.player_id != opponent_id:
                continue
            if raises == 1 and last_total >= max(13 * big_blind, 0.8 * starting_stack):
                line = OPEN_JAM
            elif last_total >= 20 * big_blind:
                line = DEEP_RAISE
            elif raises >= 2:
                line = RERAISE
            else:
                line = OPEN
        elif action == 'call' and move.player_id == opponent_id:
            if raises >= 2 or last_total >= 20 * big_blind:
                line = DEEP_RAISE if last_total >= 20 * big_blind else RERAISE
            elif line == UNKNOWN:
                line = PASSIVE
    return line

def river_size(history, opponent_id, pot, opponent_all_in):
    """Bucket the latest opponent river bet by its increment over the pot."""
    committed = 0
    increment = 0
    for move in history:
        if move.street != 'river' or move.player_id != opponent_id:
            continue
        amount = move.amount or 0
        if move.action in AGGRESSION:
            increment = amount - committed
            committed = amount
        elif move.action == 'call':
            committed += amount
    if increment <= 0 or increment >= pot:
        return None
    fraction = increment / (pot - increment)
    if opponent_all_in:
        return 'jam_overbet' if fraction >= 2.0 else 'jam'
    if fraction >= 0.75:
        return 'large'
    return 'small' if fraction < 0.4 else 'medium'

