"""Public-action history and conservative, persistent opponent estimates.

``observe`` consumes exactly the delta supplied by the organiser, including our
previous action.  Do not insert an action when returning it from ``run``: it is
reported by the engine on our next turn or in ``end_game``.

Only publicly revealed hole cards are recorded.  Showdown statistics are
selection-biased observations, not an estimate of all opponents' unseen hands.
All instance attributes are plain pickle-friendly data.
"""
from card_utils import Card, evaluate

def _new_stats():
    return {'hands': 0, 'vpip': 0, 'pfr': 0, 'threebet_opportunities': 0, 'threebets': 0, 'facing_bets': 0, 'folds_to_bet': 0, 'calls_to_bet': 0, 'raises_to_bet': 0, 'large_bets_faced': 0, 'large_bet_folds': 0, 'free_opportunities': 0, 'free_bets': 0, 'river_opportunities': 0, 'river_bets': 0, 'showdowns': 0, 'shown_categories': [0] * 9, 'shown_river_bets': 0, 'shown_river_highcard_bets': 0, 'net_chips': 0, 'net_observations': 0}

class Tracker:
    """One persistent tracker per model; ``start`` resets only hand state."""

    def __init__(self):
        self.stats = {}
        self.start([], 0)

    def start(self, hand, player_id):
        self.hand = [str(card) for card in hand]
        self.player_id = player_id
        self.teams = []
        self.history = []
        self.board = []
        self.street = 'preflop'
        self.bets = []
        self.contributions = []
        self.remaining = []
        self.initial_stacks = []
        self.folded = []
        self.shown = {}
        self.won = []
        self.pot = 0
        self.preflop_raises = 0
        self.street_raises = 0
        self.last_aggressor = None
        self.last_wager = None
        self.reconstruction_valid = True
        self.finished = False
        self._vpip = []
        self._pfr = []
        self._river_bettors = []

    def _begin(self, actions, view):
        self.teams = list(view.teams)
        count = len(self.teams)
        for name in self.teams:
            if name not in self.stats:
                self.stats[name] = _new_stats()
        self.bets = [0] * count
        self.contributions = [0] * count
        self.won = [0] * count
        self.folded = [False] * count
        self._vpip = [False] * count
        self._pfr = [False] * count
        self._river_bettors = [False] * count
        awards = [0] * count
        for action in actions:
            if action.kind == 'win':
                awards[action.player_id] += action.amount
        if view.street == 'preflop':
            self.initial_stacks = [view.stacks[p] + view.bets[p] - awards[p] for p in range(count)]
        else:
            self.initial_stacks = [None] * count
            self.reconstruction_valid = False
        self.remaining = list(self.initial_stacks)
        small = view.button if count == 2 else (view.button + 1) % count
        big = (small + 1) % count
        for player, blind in ((small, view.small_blind), (big, view.big_blind)):
            stack = self.remaining[player]
            posted = blind if stack is None else min(blind, stack)
            self.bets[player] += posted
            self.contributions[player] += posted
            self.pot += posted
            if stack is not None:
                self.remaining[player] -= posted

    def observe(self, actions, game_state):
        """Consume one engine delta; do not pass a cumulative action history."""
        if self.finished:
            return
        if not self.teams:
            self._begin(actions, game_state)
        for action in actions:
            self._consume(action)
        if self.reconstruction_valid:
            expected_stacks = [self.remaining[p] + self.won[p] for p in range(len(self.teams))]
            if self.pot != game_state.pot or tuple(self.bets) != tuple(game_state.bets) or tuple(expected_stacks) != tuple(game_state.stacks) or (self.street != game_state.street) or (self.board != [str(card) for card in game_state.board]):
                self.reconstruction_valid = False

    def _consume(self, action):
        player = action.player_id
        kind = action.kind
        if kind == 'reveal_card':
            card = str(action.card)
            if player == -1:
                self.board.append(card)
                next_street = {3: 'flop', 4: 'turn', 5: 'river'}.get(len(self.board))
                if next_street is not None:
                    self.street = next_street
                    self.bets = [0] * len(self.teams)
                    self.street_raises = 0
                    self.last_aggressor = None
                    self.last_wager = None
            else:
                self.shown.setdefault(player, []).append(card)
            self.history.append({'actor': player, 'team': None if player == -1 else self.teams[player], 'action': kind, 'street': self.street, 'card': card})
            return
        if kind == 'win':
            self.won[player] += action.amount
            self.history.append({'actor': player, 'team': self.teams[player], 'action': kind, 'street': self.street, 'amount': action.amount})
            return
        current = max(self.bets)
        owed = max(0, current - self.bets[player])
        chips = self.remaining[player]
        to_call = owed if chips is None else min(owed, chips)
        before_pot = self.pot
        previous_wager = self.last_wager
        row = {'actor': player, 'team': self.teams[player], 'action': kind, 'street': self.street, 'beforepot': before_pot, 'tocall': to_call, 'amount': action.amount, 'added': 0, 'raises_before': self.street_raises, 'bet_fraction': None}
        stats = self.stats[self.teams[player]]
        if self.street != 'preflop':
            if to_call > 0:
                stats['facing_bets'] += 1
                if kind == 'fold':
                    stats['folds_to_bet'] += 1
                elif kind == 'call':
                    stats['calls_to_bet'] += 1
                elif kind == 'raise':
                    stats['raises_to_bet'] += 1
                if previous_wager is not None:
                    row['faced_fraction'] = previous_wager['fraction']
                    if previous_wager['fraction'] >= 1.0:
                        stats['large_bets_faced'] += 1
                        if kind == 'fold':
                            stats['large_bet_folds'] += 1
            else:
                stats['free_opportunities'] += 1
                if kind == 'raise':
                    stats['free_bets'] += 1
                if self.street == 'river':
                    stats['river_opportunities'] += 1
                    if kind == 'raise':
                        stats['river_bets'] += 1
        if self.street == 'preflop' and self.preflop_raises == 1 and (owed > 0):
            stats['threebet_opportunities'] += 1
            if kind == 'raise':
                stats['threebets'] += 1
        if kind == 'fold':
            self.folded[player] = True
        else:
            added = action.amount - self.bets[player] if kind == 'raise' else to_call
            row['added'] = added
            self.bets[player] += added
            self.contributions[player] += added
            self.pot += added
            if chips is not None:
                self.remaining[player] -= added
            if self.street == 'preflop' and added > 0:
                self._vpip[player] = True
            if kind == 'raise':
                self.street_raises += 1
                self.last_aggressor = player
                fraction = (added - to_call) / max(1, before_pot + to_call)
                row['bet_fraction'] = fraction
                self.last_wager = {'actor': player, 'fraction': fraction, 'beforepot': before_pot, 'total': action.amount}
                if self.street == 'preflop':
                    self.preflop_raises += 1
                    self._pfr[player] = True
                elif self.street == 'river':
                    self._river_bettors[player] = True
        self.history.append(row)

    def finish(self, actions, game_state):
        """Consume the last delta and commit one hand; repeated finish is safe."""
        if self.finished:
            return
        self.observe(actions, game_state)
        for player, name in enumerate(self.teams):
            stats = self.stats[name]
            stats['hands'] += 1
            stats['vpip'] += int(self._vpip[player])
            stats['pfr'] += int(self._pfr[player])
            if self.reconstruction_valid:
                stats['net_chips'] += self.won[player] - self.contributions[player]
                stats['net_observations'] += 1
            shown = self.shown.get(player, [])
            if len(shown) == 2 and len(self.board) == 5:
                category = evaluate([Card.parse(c) for c in shown + self.board])[0]
                stats['showdowns'] += 1
                stats['shown_categories'][category] += 1
                if self._river_bettors[player]:
                    stats['shown_river_bets'] += 1
                    stats['shown_river_highcard_bets'] += int(category == 0)
        self.finished = True

    def profile(self, name):
        """Smoothed estimates plus raw counts; confidence gates are explicit."""
        stats = self.stats.get(name, _new_stats())
        result = dict(stats)
        result['shown_categories'] = list(stats['shown_categories'])
        result.update({'vpip_rate': (stats['vpip'] + 6) / (stats['hands'] + 10), 'pfr_rate': (stats['pfr'] + 4) / (stats['hands'] + 10), 'threebet_rate': (stats['threebets'] + 2) / (stats['threebet_opportunities'] + 12), 'fold_to_bet_rate': (stats['folds_to_bet'] + 4) / (stats['facing_bets'] + 10), 'large_fold_rate': (stats['large_bet_folds'] + 5) / (stats['large_bets_faced'] + 10), 'free_bet_rate': (stats['free_bets'] + 2) / (stats['free_opportunities'] + 6), 'river_bet_rate': (stats['river_bets'] + 2.6) / (stats['river_opportunities'] + 20), 'preflop_ready': stats['hands'] >= 30, 'response_ready': stats['facing_bets'] >= 20, 'large_response_ready': stats['large_bets_faced'] >= 15, 'river_ready': stats['river_opportunities'] >= 20})
        return result

# Component: puhguh_policy

"""Puhguh, a bounded range-aware heads-up Hold'em policy."""
from random import Random
from time import perf_counter
from player_action import PlayerAction
STRAIGHT_MASKS = (4111,) + tuple((31 << shift for shift in range(9)))
OPEN_ENDED_MASKS = tuple((15 << shift for shift in range(9)))

def _fallback(state):
    if state.can_check or (state.call_amount == 0 and state.can_call):
        return PlayerAction.call(state.my_player_id)
    if state.can_fold:
        return PlayerAction.fold(state.my_player_id)
    return PlayerAction.call(state.my_player_id) if state.can_call else PlayerAction.fold(state.my_player_id)

def _raise_to(state, amount):
    low, high = (state.min_raise_to, state.max_raise_to)
    if not (state.can_bet or state.can_raise) or low is None or high is None:
        return None
    if low > high or low - amount > state.pot_size // 2:
        return None
    return PlayerAction.raise_to(state.my_player_id, max(low, min(high, round(amount))))

def _made_value(hole, board, key, board_key, thin=False):
    """0 = check, 1â€“2 = value bet, 3 = eligible to raise for value."""
    if key <= board_key:
        return 0
    category = key >> 20
    primary = key >> 16 & 15
    secondary = key >> 12 & 15
    hole_ranks = [card // 4 + 2 for card in hole]
    board_ranks = [card // 4 + 2 for card in board]
    board_suits = [card % 4 for card in board]
    suit_count = max((board_suits.count(suit) for suit in set(board_suits)))
    rank_mask = sum((1 << rank - 2 for rank in set(board_ranks)))
    straight_texture = any(((rank_mask & mask).bit_count() >= 3 for mask in STRAIGHT_MASKS))
    dry = suit_count < 3 and (not straight_texture)
    top = max(board_ranks)
    if category >= 6:
        return 3
    if category == 5:
        flush_suit = max(set(board_suits), key=board_suits.count)
        missing_ranks = {rank for rank in range(2, 15) if (rank - 2) * 4 + flush_suit not in board}
        holds_top = (max(missing_ranks) - 2) * 4 + flush_suit in hole
        return 3 if holds_top and len(set(board_ranks)) == len(board) else 2
    if category == 4:
        if suit_count >= 4:
            return 0
        best_straight = max((high for high, mask in enumerate(STRAIGHT_MASKS, 5) if (rank_mask & mask).bit_count() >= 3))
        unpaired = len(set(board_ranks)) == len(board)
        return 3 if suit_count < 3 and unpaired and (primary == best_straight) else 2
    if category == 3:
        if primary not in hole_ranks or suit_count >= 4:
            return 0
        return 3 if dry and primary == top else 2
    if category == 2:
        pairs = (primary, secondary)
        made = [rank for rank in pairs if rank in hole_ranks and board_ranks.count(rank) < 2]
        if not made:
            return 0
        if len(made) == 2:
            return 2 if dry or (suit_count <= 3 and primary >= top) else 0
        primary = made[0]
    if category in (1, 2) and primary in hole_ranks:
        overpair = hole_ranks[0] == hole_ranks[1] > top
        kicker = max((rank for rank in hole_ranks if rank != primary), default=0)
        if dry and (overpair or (primary == top and kicker >= 12)):
            return 1
        four_straight = any(((rank_mask & mask).bit_count() >= 4 for mask in STRAIGHT_MASKS))
        return int(thin and suit_count < 3 and (not four_straight) and (overpair or (primary == top and kicker >= 10)))
    return 0

def _flop_draw_pressure(state, hole, board):
    if len(board) != 3 or not state.is_dealer:
        return False
    preflop_raiser = None
    for move in state.action_history:
        if move.street == 'preflop' and move.action in AGGRESSION:
            preflop_raiser = move.player_id
    if preflop_raiser is None or preflop_raiser != state.my_player_id:
        return False
    cards = hole + board
    suits = tuple((card % 4 for card in cards))
    if max((suits.count(suit) for suit in set(suits))) == 4:
        return True
    ranks = sum((1 << rank for rank in {card // 4 for card in cards}))
    return any((ranks & mask == mask for mask in OPEN_ENDED_MASKS))

class Policy:

    def __init__(self):
        self.ranker = ExactRanker()
        config = {'alpha': 0.35, 'value_size': 1.6, 'calibration': {'river': {'medium': 3.50946, 'small': 1.95475}, 'river_shape': {'medium': [0.3841, 0.3531, 2.3741]}}, 'adaptive_value_range': True, 'thin_value': True, 'draw_pressure': True}
        self.alpha = float(config['alpha'])
        self.size = float(config['value_size'])
        self.calibration = config.get('calibration', {})
        self.thin_value = bool(config.get('thin_value'))
        self.draw_pressure = bool(config.get('draw_pressure'))
        self.adaptive_value_range = bool(config.get('adaptive_value_range'))
        self.river_first_opportunities = 0
        self.river_first_bets = 0
        self.last_river_observation = None
        self.last_bb_river_check = None
        self.last_bb_bet_seen = False
        self.move_budget = 0.03

    def act(self, state):
        deadline = perf_counter() + self.move_budget
        fallback = _fallback(state)
        if state.my_index not in (0, 1) or len(state.stack_sizes) != 2:
            return fallback
        if len(state.hole_cards) != 2 or state.my_stack is None:
            return fallback
        hole = tuple((CARD_IDS[card] for card in state.hole_cards))
        board = tuple((CARD_IDS[card] for card in state.community_cards))
        opponent = 1 - state.my_index
        big_blind = state.big_blind or 20
        pot = state.pot_size
        cost = min(state.call_amount, state.my_stack)
        opponent_all_in = opponent < len(state.all_in) and state.all_in[opponent] or state.stack_sizes[opponent] == 0
        if len(board) == 5 and len(state.player_ids) == 2:
            opponent_id = state.player_ids[opponent]
            fingerprint = (hole, board)
            if state.is_dealer:
                first = next((move for move in state.action_history if move.street == 'river' and move.player_id == opponent_id), None)
                if first is not None and fingerprint != self.last_river_observation:
                    self.last_river_observation = fingerprint
                    self.river_first_opportunities += 1
                    self.river_first_bets += first.action in AGGRESSION
            elif self.last_bb_river_check == fingerprint and (not self.last_bb_bet_seen):
                if any((move.street == 'river' and move.player_id == opponent_id and (move.action in AGGRESSION) for move in state.action_history)):
                    self.river_first_bets += 1
                    self.last_bb_bet_seen = True
        if not board:
            action = self._preflop_action(state, hole, big_blind)
            if action is not None:
                return action
        elif len(board) >= 3:
            rank = self.ranker.rank
            key = rank(board + hole)
            board_key = rank(board) if len(board) == 5 else -1
            value = _made_value(hole, board, key, board_key, self.thin_value)
            if not cost and (not opponent_all_in):
                bet_draw = self.draw_pressure and (not value) and _flop_draw_pressure(state, hole, board)
                if value or bet_draw:
                    bet = _raise_to(state, (state.my_bet or 0) + self.size * pot)
                    if bet is not None:
                        return bet
            if value == 3 and cost and (not opponent_all_in):
                already_bet = any((move.player_id == state.my_player_id and move.street == state.street and (move.action in AGGRESSION) for move in state.action_history))
                if not already_bet:
                    target = (state.my_bet or 0) + cost + self.size * (pot + cost)
                    raise_move = _raise_to(state, target)
                    if raise_move is not None:
                        return raise_move
        if not cost or not state.can_call or pot <= 0:
            if not cost and len(board) == 5 and (not state.is_dealer) and state.can_check and (self.last_bb_river_check != (hole, board)):
                self.last_bb_river_check = (hole, board)
                self.last_bb_bet_seen = False
                self.river_first_opportunities += 1
            return fallback
        closes = opponent_all_in or cost == state.my_stack or len(board) == 5
        price = cost / (pot + cost) + (0 if closes else 0.05)
        starting_stack = (pot + sum(state.stack_sizes)) // 2
        opponent_id = state.player_ids[opponent] if len(state.player_ids) == 2 else None
        line = preflop_line(state.action_history, opponent_id, big_blind, starting_stack)
        bet_size = river_size(state.action_history, opponent_id, pot, opponent_all_in) if len(board) == 5 else None
        equity = self._equity(hole, board, line, bet_size, price, cost >= 10 * big_blind, deadline)
        return PlayerAction.call(state.my_player_id) if equity >= price else fallback

    @staticmethod
    def _preflop_action(state, hole, big_blind):
        voluntary = [move for move in state.action_history if move.street == 'preflop' and move.action in AGGRESSION | {'call'}]
        if state.is_dealer and (not voluntary):
            if button_open(*hole):
                return _raise_to(state, 2.25 * big_blind)
            return PlayerAction.fold(state.my_player_id) if state.can_fold else None
        if state.is_dealer or not value_raise(*hole) or len(voluntary) != 1:
            return None
        first = voluntary[0]
        if first.action == 'call' and state.call_amount == 0:
            return _raise_to(state, 3.5 * big_blind)
        if first.action in AGGRESSION and 0 < (first.amount or 0) <= 4 * big_blind:
            return _raise_to(state, 3.5 * first.amount)
        return None

    def _equity(self, hole, board, line, bet_size, price, costly, deadline):
        mask = sum((CARD_BITS[card] for card in board + hole))
        candidates = [(a, b, line_buckets[line]) for a, b, bits, line_buckets in PAIRS if not bits & mask]
        loose = LOOSE[line]
        sharp = SHARP[line]
        factors = self.calibration.get('preflop', {}).get(str(line), (1, 1, 1))
        if len(board) == 5:
            return self._river_equity(hole, board, candidates, loose, sharp, factors, bet_size)
        weights = self._sample_weights(candidates, loose, sharp, factors)
        unseen = [card for card in range(52) if not CARD_BITS[card] & mask]
        missing = 5 - len(board)
        hole_mask = CARD_BITS[hole[0]] | CARD_BITS[hole[1]]
        rng = Random(mask ^ hole_mask * 2654435761)
        rank = self.ranker.rank
        total = count = 0
        limit = 640 if costly else 384
        while count < limit:
            for a, b, _ in rng.choices(candidates, cum_weights=weights, k=64):
                draw = rng.sample(unseen, missing + 2)
                runout = board + tuple((card for card in draw if card != a and card != b))[:missing]
                hero_rank = rank(hole + runout)
                opponent_rank = rank((a, b) + runout)
                total += 2 if hero_rank > opponent_rank else int(hero_rank == opponent_rank)
            count += 64
            if count >= 256 and abs(total / (2 * count) - price) > 0.05:
                break
        return total / (2 * count) if count else 0.0

    def _sample_weights(self, candidates, loose, sharp, factors):
        loose_total = sum((loose[b] * factors[b] for _, _, b in candidates))
        sharp_total = sum((sharp[b] * factors[b] for _, _, b in candidates))
        weights = [factors[b] * ((1 - self.alpha) * loose[b] / loose_total + self.alpha * sharp[b] / sharp_total) for b in range(3)]
        cumulative = []
        total = 0.0
        for _, _, bucket in candidates:
            total += weights[bucket]
            cumulative.append(total)
        return cumulative

    def _river_equity(self, hole, board, candidates, loose, sharp, factors, size):
        rate = (self.river_first_bets + 2.6) / (self.river_first_opportunities + 20)
        if self.adaptive_value_range and (size == 'jam' or (size == 'jam_overbet' and rate < 0.25)):
            return self._value_river_equity(hole, board, candidates, loose, sharp, factors)
        rank = self.ranker.rank
        hero = rank(hole + board)
        scored = [(rank((a, b) + board), bucket) for a, b, bucket in candidates]
        shape = self.calibration.get('river_shape', {}).get(size)
        if shape is not None:
            ordered = sorted((score for score, _ in scored))
            low_cutoff = ordered[len(ordered) // 4]
            high_cutoff = ordered[3 * len(ordered) // 4]
            low_total = high_total = low_share = high_share = 0.0
            for score, bucket in scored:
                group = 0 if score < low_cutoff else 2 if score >= high_cutoff else 1
                factor = factors[bucket] * shape[group]
                low_weight = loose[bucket] * factor
                high_weight = sharp[bucket] * factor
                share = 1.0 if hero > score else 0.5 if hero == score else 0.0
                low_total += low_weight
                high_total += high_weight
                low_share += low_weight * share
                high_share += high_weight * share
            return (1 - self.alpha) * low_share / low_total + self.alpha * high_share / high_total
        river_fit = self.calibration.get('river', {}).get(size)
        if river_fit is not None:
            low_multiplier = high_multiplier = river_fit
        elif size in ('large', 'jam', 'jam_overbet'):
            low_multiplier, high_multiplier = (1.5, 2.0)
        else:
            low_multiplier = high_multiplier = 1.0
        cutoff = sorted((score for score, _ in scored))[3 * len(scored) // 4] if low_multiplier != 1 or high_multiplier != 1 else None
        low_total = high_total = low_share = high_share = 0.0
        for score, bucket in scored:
            low_weight = loose[bucket] * factors[bucket]
            high_weight = sharp[bucket] * factors[bucket]
            if cutoff is not None and score >= cutoff:
                low_weight *= low_multiplier
                high_weight *= high_multiplier
            low_total += low_weight
            high_total += high_weight
            share = 1.0 if hero > score else 0.5 if hero == score else 0.0
            low_share += low_weight * share
            high_share += high_weight * share
        return (1 - self.alpha) * low_share / low_total + self.alpha * high_share / high_total

    def _value_river_equity(self, hole, board, candidates, loose, sharp, factors):
        rate = (self.river_first_bets + 2.6) / (self.river_first_opportunities + 20)
        value_share = max(0.6, min(0.98, 1.14 - 1.4 * rate))
        rank = self.ranker.rank
        hero = rank(hole + board)
        board_code = rank(board)
        scored = [(rank((a, b) + board), a, b, bucket) for a, b, bucket in candidates]
        low_value_total = low_value_win = low_other_total = low_other_win = 0.0
        high_value_total = high_value_win = high_other_total = high_other_win = 0.0
        for score, a, b, bucket in scored:
            factor = factors[bucket]
            low_weight = loose[bucket] * factor
            high_weight = sharp[bucket] * factor
            win = 1.0 if hero > score else 0.5 if hero == score else 0.0
            value = _made_value((a, b), board, score, board_code, True) > 0
            if value:
                low_value_total += low_weight
                high_value_total += high_weight
                low_value_win += low_weight * win
                high_value_win += high_weight * win
            else:
                low_other_total += low_weight
                high_other_total += high_weight
                low_other_win += low_weight * win
                high_other_win += high_weight * win
        if not low_value_total or not low_other_total:
            return (1 - self.alpha) * (low_value_win + low_other_win) / (low_value_total + low_other_total) + self.alpha * (high_value_win + high_other_win) / (high_value_total + high_other_total)
        low_equity = value_share * low_value_win / low_value_total + (1 - value_share) * low_other_win / low_other_total
        high_equity = value_share * high_value_win / high_value_total + (1 - value_share) * high_other_win / high_other_total
        return (1 - self.alpha) * low_equity + self.alpha * high_equity

