"""Preserved V4 strategy adapted to the actual event's public Model API.

Fixed Monte Carlo counts make matched comparisons reproducible. Historical
100 BB results are not evidence of strength at the event's 25 BB default.
"""
from collections import namedtuple
from player_action import PlayerAction
Move = namedtuple('Move', 'street action player_id amount')

class Snapshot:

    def __init__(self, hand, player_id, tracker, view):
        self.my_player_id = self.my_index = player_id
        self.player_ids = tuple(range(view.num_players))
        self.hole_cards = tuple((str(card) for card in hand))
        self.community_cards = tuple((str(card) for card in view.board))
        self.stack_sizes = view.stacks
        self.my_stack = view.stacks[player_id]
        self.my_bet = view.bets[player_id]
        self.big_blind = view.big_blind
        self.pot_size = view.pot
        self.call_amount = view.call_amount
        self.min_raise_to, self.max_raise_to = view.raise_range or (None, None)
        self.can_bet = self.can_raise = view.can_raise
        self.can_call = self.can_fold = True
        self.can_check = self.call_amount == 0
        self.is_dealer = view.button == player_id
        self.all_in = tuple((view.status(p) == 'all_in' for p in self.player_ids))
        self.street = view.street
        self.action_history = [Move(row['street'], 'check' if row['action'] == 'call' and (not row.get('tocall', 0)) else row['action'], row['actor'], row.get('added', 0) if row['action'] == 'call' else row.get('amount', 0)) for row in tracker.history if row['action'] in ('call', 'fold', 'raise')]

class BaselineModel:

    def __init__(self):
        self.hand = []
        self.player_id = 0
        self.tracker = Tracker()
        self.policy = Policy()
        self.last_decision = {}

    def seed(self, hand, player_id):
        self.hand = list(hand)
        self.player_id = player_id
        self.tracker.start(hand, player_id)

    def run(self, actions, game_state):
        self.tracker.observe(actions, game_state)
        if game_state.num_players != 2:
            return PlayerAction.call(self.player_id) if game_state.call_amount == 0 else PlayerAction.fold(self.player_id)
        state = Snapshot(self.hand, self.player_id, self.tracker, game_state)
        action = self.policy.act(state)
        self.last_decision = {'kind': action.kind, 'amount': action.amount, 'street': game_state.street}
        return action

    def end_game(self, actions, game_state):
        self.tracker.finish(actions, game_state)

