def canonical_hand(hole):
    """Return the 169-class key for two distinct card ids or card strings."""
    if len(hole) != 2:
        raise ValueError('expected two hole cards')
    ids = []
    for card in hole:
        if isinstance(card, str):
            text = card.upper()
            if len(text) != 2 or text[0] not in '23456789TJQKA' or text[1] not in 'SHDC':
                raise ValueError('invalid card string')
            card = '23456789TJQKA'.index(text[0]) * 4 + 'SHDC'.index(text[1])
        if not isinstance(card, int) or isinstance(card, bool) or (not 0 <= card < 52):
            raise ValueError('invalid card id')
        ids.append(card)
    first, second = ids
    if first == second:
        raise ValueError('hole cards must be distinct')
    high, low = sorted((first // 4, second // 4), reverse=True)
    ranks = '23456789TJQKA'
    key = ranks[high] + ranks[low]
    return key if high == low else key + ('s' if first % 4 == second % 4 else 'o')

def lookup(hole, line, alpha=0.35):
    """Preflop showdown equity; LOOSE/SHARP are normalized before mixing.

    Valid only for the published range priors and no public board cards.
    Equity is not an EV estimate for a nonterminal betting decision.
    """
    if not isinstance(line, int) or isinstance(line, bool) or (not 0 <= line < 6):
        raise ValueError('line must be an integer from 0 through 5')
    if not 0.0 <= alpha <= 1.0:
        raise ValueError('alpha must be between zero and one')
    loose, sharp = EQUITIES[canonical_hand(hole)][line]
    return (1.0 - alpha) * loose + alpha * sharp

def standard_error(hole, line, alpha=0.35):
    """Conservative standard error bound for the blended MC estimate.

    Uses a linear bound rather than assuming independent estimates: identical
    prior scenarios deliberately share samples.
    """
    lookup(hole, line, alpha)
    loose, sharp = STANDARD_ERRORS[canonical_hand(hole)][line]
    return (1.0 - alpha) * loose + alpha * sharp

# Component: puhguh_strategy

"""Measured event experiments: range learning, bounded simulation and exploits.

All observations come from the public action stream. Monte Carlo models a
distribution of unseen opponent hands, never the actual hidden cards.
"""
from math import sqrt
from random import Random
from time import perf_counter
from player_action import PlayerAction
table_standard_error = standard_error

class ThinkingPolicy(Policy):

    def __init__(self):
        Policy.__init__(self)
        self.profile = {}
        self.flags = {}
        self.last_info = {}
        self.closing_preflop = False
        self.current_line = 0

    def act(self, state):
        self.last_info = {}
        opponent = 1 - state.my_index
        self.closing_preflop = not state.community_cards and (state.all_in[opponent] or state.call_amount >= state.my_stack)
        return Policy.act(self, state)

    def _uniform_mix(self, line):
        p = self.profile
        if not self.flags.get('ranges') or p.get('hands', 0) < 24:
            return 0.0
        if line >= 4:
            if p.get('threebet_opportunities', 0) < 16:
                return 0.0
            rate, floor = (p['threebet_rate'], 0.2)
        elif line in (2, 3):
            rate, floor = (p['pfr_rate'], 0.35)
        else:
            rate, floor = (p['vpip_rate'], 0.7)
        return min(0.95, max(0.0, (rate - floor) / max(0.01, 1 - floor)))

    def _equity(self, hole, board, line, bet_size, price, costly, deadline):
        self.current_line = line
        factors = self.calibration.get('preflop', {}).get(str(line), (1, 1, 1))
        if self.flags.get('table') and self.closing_preflop and (not board) and (tuple(factors) == (1, 1, 1)):
            mix = self._uniform_mix(line)
            q = (1 - mix) * lookup(hole, line, self.alpha) + mix * lookup(hole, 0, self.alpha)
            error = (1 - mix) * table_standard_error(hole, line, self.alpha) + mix * table_standard_error(hole, 0, self.alpha)
            self.last_info.update(equity=q, equity_source='offline_8192_sample_range_table', equity_standard_error=error, range_uniform_mix=mix, preflop_line=line, call_threshold=price)
            if abs(q - price) > max(0.012, 2 * error):
                return q
        if not self.flags.get('thinking') and (not self._uniform_mix(line)):
            return Policy._equity(self, hole, board, line, bet_size, price, costly, deadline)
        mask = sum((CARD_BITS[card] for card in board + hole))
        candidates = [(a, b, buckets[line]) for a, b, bits, buckets in PAIRS if not bits & mask]
        loose, sharp = (LOOSE[line], SHARP[line])
        if len(board) == 5:
            return self._river_equity(hole, board, candidates, loose, sharp, factors, bet_size)
        cumulative = self._sample_weights(candidates, loose, sharp, factors)
        mix = self._uniform_mix(line)
        if mix:
            total = cumulative[-1]
            cumulative = [(1 - mix) * value / total + mix * (index + 1) / len(candidates) for index, value in enumerate(cumulative)]
        unseen = [card for card in range(52) if not CARD_BITS[card] & mask]
        missing = 5 - len(board)
        hole_mask = CARD_BITS[hole[0]] | CARD_BITS[hole[1]]
        rng = Random(mask ^ hole_mask * 2654435761)
        rank = self.ranker.rank
        total = squares = count = 0
        limit = (4096 if costly else 1536) if self.flags.get('thinking') else 640 if costly else 384
        minimum = (1024 if costly else 512) if self.flags.get('thinking') else 256
        guard = perf_counter() + 0.75
        while count < limit:
            batch = min(64, limit - count)
            for a, b, _ in rng.choices(candidates, cum_weights=cumulative, k=batch):
                draw = rng.sample(unseen, missing + 2)
                runout = board + tuple((card for card in draw if card != a and card != b))[:missing]
                hero, villain = (rank(hole + runout), rank((a, b) + runout))
                share = 1.0 if hero > villain else 0.5 if hero == villain else 0.0
                total += share
                squares += share * share
            count += batch
            q = total / count
            standard_error = sqrt(max(0.0, squares / count - q * q) / count)
            margin = max(0.035, 2.5 * standard_error) if self.flags.get('thinking') else 0.05
            if count >= minimum and abs(q - price) > margin:
                break
            if perf_counter() >= guard:
                break
        self.last_info.update(equity=q, equity_samples=count, equity_standard_error=standard_error, range_uniform_mix=mix, preflop_line=line, call_threshold=price, simulation_guard_hit=perf_counter() >= guard)
        return q

    def _river_equity(self, hole, board, candidates, loose, sharp, factors, size):
        p = self.profile
        old_adaptive = self.adaptive_value_range
        gate = bool(self.flags.get('river_gate') and p.get('river_opportunities', 0) >= 12 and (p['river_bet_rate'] >= 0.35))
        if self.flags.get('river_gate') and p.get('river_opportunities', 0) >= 12:
            self.river_first_opportunities = p['river_opportunities']
            self.river_first_bets = p['river_bets']
            if gate:
                self.adaptive_value_range = False
        q = Policy._river_equity(self, hole, board, candidates, loose, sharp, factors, size)
        self.adaptive_value_range = old_adaptive
        mix = self._uniform_mix(self.current_line)
        if mix and p.get('river_opportunities', 0) >= 12 and (p['river_bet_rate'] >= 0.35):
            rank = self.ranker.rank
            hero = rank(hole + board)
            random_q = sum((1 if hero > score else 0.5 if hero == score else 0 for score in (rank((a, b) + board) for a, b, _ in candidates))) / len(candidates)
            q = (1 - mix) * q + mix * random_q
        else:
            mix = 0.0
        self.last_info.update(equity=q, equity_exact_combinations=len(candidates), river_size_bucket=size, learned_river_bet_rate=p.get('river_bet_rate'), range_uniform_mix=mix, adaptive_value_range_used=bool(old_adaptive and (not gate) and (size == 'jam' or (size == 'jam_overbet' and (self.river_first_bets + 2.6) / (self.river_first_opportunities + 20) < 0.25))))
        return q

class EventModel(BaselineModel):
    FLAGS = {'thinking': True, 'ranges': True, 'river_gate': True, 'fourbet': True, 'exploit': True, 'table': True, 'value_guard': True}

    def __init__(self):
        BaselineModel.__init__(self)
        self.policy = ThinkingPolicy()
        self.policy.flags = dict(self.FLAGS)
        self.decision_info = {}
        self.river_responses = {}
        self.river_bluff_pending = False

    def seed(self, hand, player_id):
        BaselineModel.seed(self, hand, player_id)
        self.river_bluff_pending = False

    def run(self, actions, game_state):
        self.tracker.observe(actions, game_state)
        me = self.player_id
        if game_state.num_players != 2:
            return PlayerAction.call(me) if game_state.call_amount == 0 else PlayerAction.fold(me)
        state = Snapshot(self.hand, me, self.tracker, game_state)
        opponent = game_state.teams[1 - me]
        profile = self.tracker.profile(opponent)
        responses = self.river_responses.get(opponent, {'faced': 0, 'folded': 0})
        profile.update(river_large_bets_faced=responses['faced'], river_large_fold_rate=(responses['folded'] + 5) / (responses['faced'] + 10))
        self.policy.profile = profile
        self.decision_info = {'profile': profile}
        if self.river_bluff_pending and state.call_amount:
            self.decision_info['reason'] = 'fold_to_raise_after_pure_river_bluff'
            return PlayerAction.fold(me)
        action = self._preflop_exploit(state, profile)
        if action is not None:
            return action
        action = self.policy.act(state)
        self.decision_info.update(self.policy.last_info)
        guarded = self._value_guard(state, action)
        if guarded is not None:
            return guarded
        alternative = self._river_bluff(state, profile, action)
        if alternative is not None:
            return alternative
        self.decision_info['reason'] = 'range_equity_and_value'
        return action

    def _preflop_exploit(self, state, profile):
        if state.community_cards:
            return None
        flags = self.policy.flags
        hole = tuple((CARD_IDS[card] for card in state.hole_cards))
        high, low = sorted((card // 4 + 2 for card in hole), reverse=True)
        raises = [move for move in state.action_history if move.action in AGGRESSION]
        if flags.get('fourbet') and len(raises) >= 2 and (state.my_stack > state.call_amount):
            kk = high == low >= 13
            wide = profile.get('threebet_opportunities', 0) >= 16 and profile['threebet_rate'] > 0.2
            qqak = high == low >= 12 or (high == 14 and low == 13)
            if kk or (wide and qqak):
                action = _raise_to(state, state.my_stack + state.my_bet)
                if action is not None:
                    self.decision_info['reason'] = 'premium_short_stack_fourbet'
                    return action
        if flags.get('exploit') and state.is_dealer and (not state.action_history):
            if profile.get('hands', 0) >= 30 and profile['vpip_rate'] < 0.3:
                action = _raise_to(state, 2.25 * state.big_blind)
                if action is not None:
                    self.decision_info['reason'] = 'steal_against_observed_tight_defence'
                    return action
        return None

    def _value_guard(self, state, chosen):
        if not self.policy.flags.get('value_guard') or len(state.community_cards) != 5 or state.call_amount or (chosen.kind != 'raise'):
            return None
        hole = tuple((CARD_IDS[card] for card in state.hole_cards))
        board = tuple((CARD_IDS[card] for card in state.community_cards))
        rank = self.policy.ranker.rank
        hero = rank(hole + board)
        suits = [card % 4 for card in board]
        four_suit = next((suit for suit in set(suits) if suits.count(suit) == 4), None)
        if four_suit is not None and hero >> 20 == 5:
            missing = sorted((card for card in range(four_suit, 52, 4) if card not in board), reverse=True)
            held = [card for card in hole if card % 4 == four_suit]
            if held and max(held) < missing[1]:
                self.decision_info['reason'] = 'check_vulnerable_flush_on_four_suit_river'
                return PlayerAction.call(self.player_id)
        board_ranks = [card // 4 for card in board]
        if hero >> 20 == 2 and sum((board_ranks.count(r) == 2 for r in set(board_ranks))) == 2:
            self.decision_info['reason'] = 'check_thin_value_on_double_paired_river'
            return PlayerAction.call(self.player_id)
        return None

    def _river_bluff(self, state, profile, chosen):
        if not self.policy.flags.get('exploit') or len(state.community_cards) != 5 or state.call_amount or (chosen.kind != 'call') or (not state.is_dealer) or (profile.get('river_large_bets_faced', 0) < 12):
            return None
        hole = tuple((CARD_IDS[card] for card in state.hole_cards))
        board = tuple((CARD_IDS[card] for card in state.community_cards))
        rank = self.policy.ranker.rank
        hero = rank(hole + board)
        if _made_value(hole, board, hero, rank(board), True):
            return None
        mask = sum((CARD_BITS[card] for card in hole + board))
        scores = [rank((a, b) + board) for a, b, bits, _ in PAIRS if not bits & mask]
        equity = sum((1 if hero > score else 0.5 if hero == score else 0 for score in scores)) / len(scores)
        if equity > 0.2:
            return None
        n = profile['river_large_bets_faced'] + 10
        f = profile['river_large_fold_rate']
        lower = max(0.0, f - 1.96 * sqrt(f * (1 - f) / (n + 1)))
        action = _raise_to(state, state.my_bet + state.pot_size)
        if action is None:
            return None
        bet = action.amount - state.my_bet
        if bet < state.pot_size:
            return None
        bet_ev = lower * state.pot_size - (1 - lower) * bet
        check_ev = equity * state.pot_size
        if bet_ev <= check_ev + 0.08 * state.pot_size:
            return None
        self.decision_info.update(reason='confidence_gated_river_bluff', fold_probability_lower=lower, bet_ev_lower=bet_ev, check_ev_proxy=check_ev, equity_random_range=equity)
        self.river_bluff_pending = True
        return action

    def end_game(self, actions, game_state):
        if self.tracker.finished:
            return
        BaselineModel.end_game(self, actions, game_state)
        for row in self.tracker.history:
            if row['street'] == 'river' and row.get('tocall', 0) > 0 and (row.get('faced_fraction', 0) >= 1):
                counts = self.river_responses.setdefault(row['team'], {'faced': 0, 'folded': 0})
                counts['faced'] += 1
                counts['folded'] += int(row['action'] == 'fold')

class ThinkOnly(EventModel):
    FLAGS = {'thinking': True}

class RangeOnly(EventModel):
    FLAGS = {'ranges': True}

class RiverOnly(EventModel):
    FLAGS = {'river_gate': True}

class FourbetOnly(EventModel):
    FLAGS = {'fourbet': True}

class ExploitOnly(EventModel):
    FLAGS = {'exploit': True}

class TableOnly(EventModel):
    FLAGS = {'table': True}

class ValueGuardOnly(EventModel):
    FLAGS = {'value_guard': True}

# Component: puhguh_refined

"""Isolated refinement of close, closing-preflop table decisions.

The frozen policy can discard its 8,192-sample table estimate when a call is
close and replace it with fewer live samples. This experiment retains that
evidence and combines it with the independent live Monte Carlo estimate.
It changes no other strategic flags, betting decisions, or opponent priors.
"""
from math import sqrt
TABLE_EFFECTIVE_SAMPLES = 8192
UNCERTAINTY_SCOPE = 'approximate Monte Carlo sampling error; excludes opponent range uncertainty and optional-stopping effects'

class RefinedPolicy(ThinkingPolicy):

    def __init__(self):
        ThinkingPolicy.__init__(self)
        self.preflop_equities = EQUITIES
        self.preflop_standard_errors = STANDARD_ERRORS
        self.preflop_metadata = METADATA

    def _equity(self, hole, board, line, bet_size, price, costly, deadline):
        factors = self.calibration.get('preflop', {}).get(str(line), (1, 1, 1))
        use_table = self.flags.get('table') and self.closing_preflop and (not board) and (tuple(factors) == (1, 1, 1))
        if not use_table:
            return ThinkingPolicy._equity(self, hole, board, line, bet_size, price, costly, deadline)
        self.current_line = line
        mix = self._uniform_mix(line)
        table_q = (1 - mix) * lookup(hole, line, self.alpha) + mix * lookup(hole, 0, self.alpha)
        table_error = (1 - mix) * standard_error(hole, line, self.alpha) + mix * standard_error(hole, 0, self.alpha)
        table_info = {'equity': table_q, 'equity_source': 'offline_8192_sample_range_table', 'equity_standard_error': table_error, 'equity_uncertainty_scope': UNCERTAINTY_SCOPE, 'equity_effective_samples': TABLE_EFFECTIVE_SAMPLES, 'table_equity': table_q, 'table_standard_error': table_error, 'table_effective_samples': TABLE_EFFECTIVE_SAMPLES, 'mc_equity_samples': 0, 'range_uniform_mix': mix, 'preflop_line': line, 'call_threshold': price}
        if not self.flags.get('thinking') or abs(table_q - price) > max(0.012, 2 * table_error):
            self.last_info.update(table_info)
            return table_q
        original_table_flag = self.flags['table']
        self.flags['table'] = False
        try:
            mc_q = ThinkingPolicy._equity(self, hole, board, line, bet_size, price, costly, deadline)
        finally:
            self.flags['table'] = original_table_flag
        count = self.last_info.get('equity_samples', 0)
        if count <= 0:
            self.last_info.update(table_info)
            self.last_info['refinement_no_new_samples'] = True
            return table_q
        mc_error = self.last_info.get('equity_standard_error', 0.5 / sqrt(count))
        total = TABLE_EFFECTIVE_SAMPLES + count
        table_weight = TABLE_EFFECTIVE_SAMPLES / total
        mc_weight = count / total
        combined_q = table_weight * table_q + mc_weight * mc_q
        combined_error = sqrt((table_weight * table_error) ** 2 + (mc_weight * mc_error) ** 2)
        self.last_info.update(table_info)
        self.last_info.update(equity=combined_q, equity_source='offline_table_plus_independent_monte_carlo', equity_standard_error=combined_error, equity_effective_samples=total, table_weight=table_weight, mc_weight=mc_weight, mc_equity=mc_q, mc_equity_samples=count, mc_standard_error=mc_error)
        return combined_q

class RefinedEventModel(EventModel):

    def __init__(self):
        EventModel.__init__(self)
        self.policy = RefinedPolicy()
        self.policy.flags = dict(self.FLAGS)

class RefinedTableOnly(RefinedEventModel):
    FLAGS = {'table': True}

# Component: puhguh_context

"""Unselected context-gate experiment; no changes to frozen candidates.

Wide preflop participation alone does not establish wide postflop betting.
Uniform range mixing after the flop additionally requires repeated public
betting opportunities and a one-sided approximate Beta-posterior lower bound
above one half. This fixed diagnostic hypothesis still requires matched tests.
"""
from math import sqrt

class ContextPolicy(RefinedPolicy):

    def __init__(self):
        RefinedPolicy.__init__(self)
        self.current_street = 'preflop'

    def _postflop_context(self):
        opportunities = self.profile.get('free_opportunities', 0)
        observations = opportunities + 6
        mean = self.profile.get('free_bet_rate', 2 / observations)
        lower = mean - 1.645 * sqrt(max(0.0, mean * (1 - mean) / (observations + 1)))
        allowed = opportunities >= 20 and lower > 0.5
        return {'postflop_range_gate_applies': self.current_street != 'preflop', 'postflop_range_gate_passed': allowed, 'postflop_free_opportunities': opportunities, 'postflop_free_bet_rate': mean, 'postflop_free_bet_lower_95_approx': lower}

    def _uniform_mix(self, line):
        original = ThinkingPolicy._uniform_mix(self, line)
        if self.current_street == 'preflop' or original <= 0:
            return original
        return original if self._postflop_context()['postflop_range_gate_passed'] else 0.0

    def _equity(self, hole, board, line, bet_size, price, costly, deadline):
        equity = RefinedPolicy._equity(self, hole, board, line, bet_size, price, costly, deadline)
        original = ThinkingPolicy._uniform_mix(self, line)
        context = self._postflop_context()
        self.last_info.update(context)
        self.last_info.update(range_uniform_mix_before_context=original, postflop_uniform_mix_blocked=bool(context['postflop_range_gate_applies'] and original > 0 and (not context['postflop_range_gate_passed'])))
        return equity

    def act(self, state):
        self.current_street = state.street
        action = RefinedPolicy.act(self, state)
        self.last_info.update(self._postflop_context())
        return action

class ContextModel(RefinedEventModel):

    def __init__(self):
        RefinedEventModel.__init__(self)
        self.policy = ContextPolicy()
        self.policy.flags = dict(self.FLAGS)

# Component: puhguh_value_context

"""Unselected value-guard exception for strongly observed calling stations.

The public response sample is conditional on the bets that were faced. Its
normal approximation to a Beta-posterior lower bound is a decision gate, not
an EV guarantee for a particular river or bet size. All other context-policy
decisions and feature switches are preserved.
"""
from math import sqrt

class ContextValueModel(ContextModel):

    def __init__(self):
        ContextModel.__init__(self)
        self.strategy_variant = 'context_value'

    def _value_guard(self, state, chosen):
        guarded = ContextModel._value_guard(self, state, chosen)
        if guarded is None:
            return None
        observations = self.policy.profile.get('facing_bets', 0)
        calls = self.policy.profile.get('calls_to_bet', 0)
        mean = (calls + 6) / (observations + 10)
        lower = mean - 1.645 * sqrt(max(0.0, mean * (1 - mean) / (observations + 11)))
        hands = self.policy.profile.get('hands', 0)
        vpip = self.policy.profile.get('vpip_rate', (self.policy.profile.get('vpip', 0) + 6) / (hands + 10))
        vpip_lower = vpip - 1.645 * sqrt(max(0.0, vpip * (1 - vpip) / (hands + 11)))
        calls_pass = observations >= 30 and lower > 0.8
        participation_pass = hands >= 30 and vpip_lower > 0.5
        override = calls_pass and participation_pass
        self.decision_info.update(value_guard_station_override=override, value_guard_station_observations=observations, value_guard_station_calls=calls, value_guard_station_call_rate=mean, value_guard_station_call_lower_95_approx=lower, value_guard_station_call_gate_passed=calls_pass, value_guard_station_vpip_observations=hands, value_guard_station_vpip_rate=vpip, value_guard_station_vpip_lower_95_approx=vpip_lower, value_guard_station_vpip_gate_passed=participation_pass, value_guard_original_reason=self.decision_info.get('reason'))
        return None if override else guarded

# Component: selected_entry

class Model(ContextValueModel):
    """Puhguh event submission selected by matched benchmarks."""
